// --- 0. INICIALIZACIÓN DE RESULTADOS ---
const resultadosFinales = [];
const todosLosItemsDeAlertas = $('If1').all();
const todosLosItemsDeTags = $input.all();

// --- BUCLE PRINCIPAL ---
for (let i = 0; i < todosLosItemsDeAlertas.length; i++) {
    const itemAlertas = todosLosItemsDeAlertas[i];
    const itemTag = todosLosItemsDeTags[i];

    // --- 1. INICIALIZACIÓN POR ITEM ---
    const alertasTexto = itemAlertas.json.alertas || [];
    const mensajeEtiquetado = itemTag.json.final || "";
    let listaCampañasActivasSimple = null; 

    const reporteConsolidado = {
        cliente: null,
        empresa: null,
        idCuenta: null,
        alertasMetricas: [],
        alertasEstructurales: [],
        avisoFases: { // Objeto para el aviso de fases faltantes
            faltantes: null,
            activas: null
        },
        avisoProgreso: [] // <-- NUEVO: Para alertas de "Listo para Fase 5"
    };

    // --- 2. EXPRESIONES REGULARES ---
    const regexCliente = /\*Cliente:\* (.*?)\n/;
    const regexEmpresa = /\*Empresa:\* (.*?)\n/;
    // Regex de ID modificada para aceptar ambos formatos
    const regexIdCuenta = /\*ID Cuenta(?: Publicitaria)?:\* (.*?)\n/;
    const regexCampañaMetrica = /\*Campaña:\* (.*?)\n\*Fecha de creación:\* (.*?)\n\*Estado:\* (.*?)\n\*Razón:\* (.*)/;
    const regexAlertaEstructuralSimple = /AVISO: (.*?)\n/;
    const regexCampañasActivasSimple = /\*Campañas Activas:\*\n((?:• .+\n?)+)/m;
    const regexFasesFaltantes = /\*Fases Faltantes:\*\n((?:❌ .+\n?)+)/m;
    const regexCampañasActivasEnAvisoFases = /\*Campañas Activas Actualmente:\*\n((?:• .+\n?)+)/m;

    // --- NUEVA REGEX ---
    // Captura el título (Grupo 1) y el motivo (Grupo 2) de la alerta de progreso
    const regexAvisoProgreso = /✅ (Listo para Fase 5)\n\n(?:[\s\S]*?)\*Motivo:\* ([\s\S]*)/;


    // --- 3. ANÁLISIS Y CONSOLIDACIÓN DE ALERTAS (LÓGICA MEJORADA) ---
    for (const texto of alertasTexto) {

        // --- Lógica de extracción de datos MEJORADA ---
        // Intenta llenar los campos faltantes en CADA iteración
        if (!reporteConsolidado.cliente) {
            reporteConsolidado.cliente = texto.match(regexCliente)?.[1] || null;
        }
        if (!reporteConsolidado.empresa) {
            reporteConsolidado.empresa = texto.match(regexEmpresa)?.[1] || null;
        }
        if (!reporteConsolidado.idCuenta) {
            reporteConsolidado.idCuenta = texto.match(regexIdCuenta)?.[1] || null;
        }
        // --- Fin de la lógica de extracción ---


        // Se prioriza la búsqueda del aviso más complejo primero
        if (texto.includes("Faltan Fases de Campañas Activas")) {
            reporteConsolidado.alertasEstructurales.push({ descripcion: "Faltan Fases de Campañas Activas" });
            const matchFaltantes = texto.match(regexFasesFaltantes);
            if (matchFaltantes) {
                reporteConsolidado.avisoFases.faltantes = matchFaltantes[1].trim();
            }
            const matchActivas = texto.match(regexCampañasActivasEnAvisoFases);
            if (matchActivas) {
                reporteConsolidado.avisoFases.activas = matchActivas[1].trim();
            }

        // --- NUEVO BLOQUE "ELSE IF" ---
        } else if (texto.startsWith("✅ Listo para Fase 5")) {
            const matchProgreso = texto.match(regexAvisoProgreso);
            if (matchProgreso) {
                reporteConsolidado.avisoProgreso.push({
                    titulo: matchProgreso[1].trim(), // "Listo para Fase 5"
                    motivo: matchProgreso[2].trim()  // "Han pasado +7 días..."
                });
            }
        // --- FIN NUEVO BLOQUE ---

        } else if (texto.includes("*Razón:*")) { // Alertas de métricas
            const esRepetida = texto.startsWith("ALERTA REPETIDA");
            const campañasIndividuales = texto.split('-----------------------------------');
            for (const seccionCampaña of campañasIndividuales) {
                const match = seccionCampaña.match(regexCampañaMetrica);
                if (match) {
                    reporteConsolidado.alertasMetricas.push({
                        esRepetida: esRepetida,
                        campaña: match[1].trim(),
                        razon: match[4].trim()
                    });
                }
            }
        } else { // Otros avisos estructurales simples
            const match = texto.match(regexAlertaEstructuralSimple);
            if (match) {
                reporteConsolidado.alertasEstructurales.push({
                    descripcion: match[1].trim()
                });
            }
            const matchActivasSimple = texto.match(regexCampañasActivasSimple);
            if (matchActivasSimple) {
                listaCampañasActivasSimple = matchActivasSimple[1].trim();
            }
        }
    }

    // --- 4. CONSTRUCCIÓN DEL MENSAJE DE SLACK ---
    const blocks = [];
    // Header modificado para usar empresa o cliente como fallback
    const nombreDisplay = reporteConsolidado.empresa || reporteConsolidado.cliente || 'Cliente';
    blocks.push({ "type": "header", "text": { "type": "plain_text", "text": `🚨 Alertas para ${nombreDisplay}`, "emoji": true } });

    if (mensajeEtiquetado) {
        blocks.push({ "type": "context", "elements": [{ "type": "mrkdwn", "text": mensajeEtiquetado }] });
    }

    // Usar fallbacks por si algún dato no se encontró
    blocks.push({ "type": "section", "fields": [{ "type": "mrkdwn", "text": `*Cliente:*\n${reporteConsolidado.cliente || 'No encontrado'}` }, { "type": "mrkdwn", "text": `*ID Cuenta:*\n${reporteConsolidado.idCuenta || 'No encontrado'}` }] });
    blocks.push({ "type": "divider" });

    // --- NUEVO BLOQUE PARA AVISO DE PROGRESO (Fase 5) ---
    if (reporteConsolidado.avisoProgreso.length > 0) {
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": "🚀 *Acciones Recomendadas*" } });
        for (const aviso of reporteConsolidado.avisoProgreso) {
            // Se muestra el título y el motivo capturados por la regex
            blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": `*${aviso.titulo}*\n${aviso.motivo}` } });
        }
        blocks.push({ "type": "divider" });
    }
    // --- FIN NUEVO BLOQUE ---

    if (reporteConsolidado.alertasMetricas.length > 0) {
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": "*🔎 Alertas de Métricas (Prioritarias)*" } });
        for (const alerta of reporteConsolidado.alertasMetricas) {
            const etiquetaRepetida = alerta.esRepetida ? "`REPETIDA` " : "";
            blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": `${etiquetaRepetida}*Campaña:* ${alerta.campaña}\n*Razón:* ${alerta.razon}` } });
        }
        blocks.push({ "type": "divider" });
    }

    if (reporteConsolidado.alertasEstructurales.length > 0) {
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": "*🔧 Alertas de Estructura*" } });
        for (const alerta of reporteConsolidado.alertasEstructurales) {
            blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": `• ${alerta.descripcion}` } });
        }
        // No se pone divider aquí para que el detalle de fases aparezca junto
    }

    // Bloque para el aviso detallado de FASES FALTANTES
    if (reporteConsolidado.avisoFases.faltantes) {
        let detallesTexto = `\n*Fases Faltantes:*\n${reporteConsolidado.avisoFases.faltantes}`;
        if (reporteConsolidado.avisoFases.activas) {
            detallesTexto += `\n\n*Campañas Activas Actualmente:*\n${reporteConsolidado.avisoFases.activas}`;
        }
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": detallesTexto } });
        blocks.push({ "type": "divider" });
    }

    // Bloque para la lista de campañas de avisos simples
    if (listaCampañasActivasSimple) {
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": "*📊 Campañas Activas en la Cuenta*" } });
        blocks.push({ "type": "section", "text": { "type": "mrkdwn", "text": listaCampañasActivasSimple } });
        blocks.push({ "type": "divider" });
    }

    // Lógica de botones (no se modifica)
    if (reporteConsolidado.alertasMetricas.length > 0 || reporteConsolidado.alertasEstructurales.length > 0 || reporteConsolidado.avisoProgreso.length > 0) {
      // Se añade avisoProgreso a la condición para mostrar botones
      blocks.push({ "type": "actions", "elements": [ { "type": "button", "text": { "type": "plain_text", "text": "Campañas Ajustadas", "emoji": true }, "style": "primary", "value": `revisado_${reporteConsolidado.idCuenta}`, "action_id": "approve_button" }, { "type": "button", "text": { "type": "plain_text", "text": "Dependencia", "emoji": true }, "value": `dependencia_${reporteConsolidado.idCuenta}`, "action_id": "dependencia_button" } ] });
    }

    resultadosFinales.push({ json: { slack_block: { "blocks": blocks } } });
}

// --- 6. RETORNAR TODOS LOS RESULTADOS ---
return resultadosFinales;

